insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs6-factsheets', 'International Institute for Population Sciences (IIPS) / Ministry of Health and Family Welfare', 'National Family Health Survey (NFHS-6), 2023-24: India and State/UT Fact Sheets (May 2026)', 'https://www.nfhsiips.in/nfhsuser/assets/National%20Family%20Health%20Survey%20(NFHS-6)%202023-2024%20Fact%20Sheets.pdf', 'A', 'Government of India publication', 'Household survey (679,238 households, 716,397 women, 100,977 men); fact sheets print NFHS-6 Urban/Rural/Total and NFHS-5 Total side by side. Total column used.', 'India and 35 states/UTs; Manipur not surveyed', 'Provisional results. The NFHS-6 fact sheets do not print improved sanitation or clean cooking fuel. Fieldwork ran from May 2023 to Dec 2024 in two phases, so state reference years differ (2023 or 2024).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs1-india-report', 'International Institute for Population Sciences (IIPS), Bombay (copy hosted by The DHS Program, ICF)', 'National Family Health Survey (MCH and Family Planning), India 1992-93 (August 1995)', 'https://dhsprogram.com/pubs/pdf/FRIND1/FRIND1.pdf', 'A', 'Government of India / IIPS publication', 'Household survey 1992-93; Table 3.12 Housing characteristics by state (% of households).', 'India and 24 states plus Jammu region of J&K; no Sikkim, no Kashmir region', 'The PDF is a scan; values come from its OCR text layer. Pre-2000 undivided MP/UP/Bihar, undivided AP.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs2-india-report', 'International Institute for Population Sciences (IIPS) and ORC Macro (copy hosted by The DHS Program, ICF)', 'National Family Health Survey (NFHS-2), 1998-99: India (2000)', 'https://dhsprogram.com/pubs/pdf/FRIND2/FRIND2.pdf', 'A', 'Government of India / IIPS publication', 'Household survey 1998-99; Table 2.12 Housing characteristics by state (% of households).', 'India and 25 states; Tripura not in report (fieldwork delayed)', 'Undivided MP/UP/Bihar and AP. Water and fuel columns (piped or hand pump; biomass) don''t match the requested indicators, so they weren''t used.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
